import React from 'react'
import { useNavigate } from 'react-router-dom' // Keep this if you want navigation
import NavBar from '../Components/NavBar'
import Footer from '../Components/Footer'
import './advertisements.css'

const posters = [
  {
    id: 1,
    title: 'T-shirt Design Course',
    imageUrl: '/Images/home1.jpeg',
    description: 'Master the art of T-shirt design, from concept to final print-ready files, using industry-standard tools.',
    tag: 'Beginner Friendly' // Added more relevant data
  },
  {
    id: 2,
    title: 'Batik Techniques',
    imageUrl: '/Images/home2.jpeg',
    description: 'Explore traditional and modern Batik methods, focusing on intricate wax resists and vibrant dye applications.',
    tag: 'Intermediate'
  },
  {
    id: 3,
    title: 'Screen Printing Workshop',
    imageUrl: '/Images/home2.jpeg',
    description: 'Hands-on training for multi-color screen printing on fabric and paper, covering exposure and registration.',
    tag: 'Workshop'
  }
]

export default function Advertisements() {
  const navigate = useNavigate()

  const goToDetail = (poster) => {
    // This function can be used to navigate or handle the button click
    navigate(`/advertisement/${poster.id}`, { state: poster })
  }

  return (
    <div className="advertisements-page">
      <NavBar />
      
      <main className="content-area">
        <header className="page-header">
          <h1>Creative Workshops & Courses 🎨</h1>
          <p>Explore a range of hands-on courses in textile design and printing!</p>
        </header>

        <section className="posters-grid">
          {posters.map((poster) => (
            <article 
              key={poster.id} 
              className="poster-card"
              // Removed onClick from the whole card to allow button to handle it
            >
              <div className="poster-image-wrapper">
                <img src={poster.imageUrl} alt={poster.title} className="poster-image" />
              </div>
              <div className="poster-info">
                <h3 className="poster-title">{poster.title}</h3>
                <p className="poster-description">{poster.description}</p>
                {/* Display a tag/price if available */}
                {poster.tag && <p className="poster-tag">**{poster.tag}**</p>}
                
              </div>
            </article>
          ))}
        </section>
      </main>

      <Footer />
    </div>
  )
}
